 void render(){colors=AppPalette.of(this);getWindow().setStatusBarColor(colors.bg);getWindow().setNavigationBarColor(colors.bg);LinearLayout root=PlusUi.column(this);root.setBackgroundColor(colors.bg);root.setFitsSystemWindows(true);if(Build.VERSION.SDK_INT>=35){root.setFitsSystemWindows(false);root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(PlusUi.dp(this,12)+bars.left,PlusUi.dp(this,6)+bars.top,PlusUi.dp(this,12)+bars.right,PlusUi.dp(this,6)+bars.bottom);return insets;});}LinearLayout head=new LinearLayout(this);View back=PlusUi.backButton(this,colors,this::finish);LinearLayout.LayoutParams backParams=new LinearLayout.LayoutParams(PlusUi.dp(this,44),PlusUi.dp(this,44));backParams.rightMargin=PlusUi.dp(this,12);head.setGravity(Gravity.CENTER_VERTICAL);head.setPadding(PlusUi.dp(this,12),PlusUi.dp(this,8),PlusUi.dp(this,12),PlusUi.dp(this,4));head.addView(back,backParams);TextView title=PlusUi.text(this,"Ferramentas",23);ThemeStyle.title(title,23);head.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(head);ScrollView scroll=new ScrollView(this);content=PlusUi.column(this);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));TextView signature=PlusUi.text(this,"Haidoy Carlos Mautempo",10);signature.setGravity(Gravity.CENTER);root.addView(signature);setContentView(root);section("Biblioteca");action("tasks","Tarefas em segundo plano",()->TaskService.open(this));action("import","Pastas de importação",()->ImportWork.folders(this));action("search","Pesquisar no conteúdo",()->LibrarySearchActivity.open(this));action("collection","Colecções",()->BookCategories.manage(this,()->{}));action("book","Bíblias importadas",this::bibles);section("Leitura e voz");action("speaker","Vozes naturais do Google",()->NaturalVoicesActivity.open(this));action("tune","Detectar motores TTS",()->VoiceEnginesActivity.open(this));action("book","Consultar passagem bíblica",()->BibleLinks.query(this));action("widget","Adicionar widget de leitura",()->ReadingWidget.pin(this));action("android","Instalar aplicação Android",()->{try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(ApkInstallActivity.MIME),94);}catch(Exception e){PlusUi.error(this,e);}});action("speed","Desempenho",()->PlusUi.performance(this));action("dictionary","Dicionário de pronúncia",()->PlusUi.dictionary(this));action("scan","Dados de OCR",this::ocr);section("Estudos e cópias");action("storage","Armazenamento",()->StorageActivity.open(this));action("pdfbook","Caderno de revisão em PDF",revision::choose);action("restore","Cópia e recuperação",backup::show);action("shield","Licenças",this::licenses);if(page.equals("bibles")){page="home";bibles();}else if(page.equals("backup")){page="home";backup.show();}else if(page.equals("revision")){page="home";revision.choose();}}
