 void bibles(){PlusUi.run(this,()->{List<StudyStore.Row> rows;try(PlusStore db=new PlusStore(this)){rows=db.rows("bible_sources",null,null,"title COLLATE NOCASE",1000);}PlusUi.post(this,()->{UiPanel panel=new UiPanel(this,"Bíblias importadas",null,"book");panel.action("globe","Descarregar Bíblias","Mais de 1500 versões em 1200 línguas (eBible.org)",false,()->BibleCatalog.show(this));panel.action("add","Importar ficheiro bíblico","MyBible SQLite3, USX, ZIP, TXT ou livro",false,this::pickBible);panel.action("import","Importar pasta USX","Uma versão, incluindo subpastas como USX_1",false,this::pickUsxFolder);panel.action("book","Almeida · ACF / ARA","Importar a sua edição",false,()->new UiDialog.Builder(this).setTitle("Almeida").setItems(new String[]{"ACF","ARA"},(d,n)->pickBible(n==0?"ACF":"ARA")).show());panel.action("book","Bíblia Amplificada","Importar a sua edição",false,()->pickBible("Bíblia Amplificada"));panel.action("book","A Mensagem","Importar a sua edição",false,()->pickBible("A Mensagem"));panel.action("book","Usar Bíblia da biblioteca",null,false,()->BibleWork.library(this));panel.action("contents","Comentários bíblicos (MyBible)",BibleComments.all(this).isEmpty()?AppLanguage.text(this,"Carregar um ficheiro .commentaries"):BibleComments.title(this,BibleComments.chosen(this)),false,this::commentaries);panel.action("search","Consultar passagem bíblica","Isaías 3.1-7, 12 · Jo 3:16 · Salmo 23",false,()->BibleLinks.query(this));panel.action("bookmark","Passagens guardadas","Guardadas na leitura rápida",false,()->BibleLinks.saved(this));panel.action("calendar","Estudo bíblico","Leitura diária e semanal, decorar",false,()->BibleStudyActivity.open(this));panel.action("star","Jogo da Bíblia","3 níveis, 10 perguntas e recordes",false,()->BibleGameActivity.open(this));panel.action("info","Formato de importação",null,false,()->new UiDialog.Builder(this).setTitle("Formatos de Bíblia").setMessage("MyBible: seleccione o módulo .SQLite3 (por exemplo ARAi+.SQLite3 ou ARM’67.SQLite3), mesmo que o Android o mostre como BIN. Ficheiros .search são índices; .commentaries, .dictionary e .plan não são texto bíblico.\n\nUSX: pode importar um livro .usx, um ZIP com uma versão ou escolher a pasta da versão/USX_1. Ficheiros styles.xml, LDML, VRS e JPG são auxiliares e ficam de fora. Escolha uma só versão de cada vez.\n\nMantém TXT, CSV, TSV, USFM, EPUB, PDF e DOCX com texto, incluindo UTF-8, UTF-16 com BOM e Windows-1252. Os textos integrais das traduções não acompanham o aplicativo.").setPositiveButton("Fechar",null).show());for(StudyStore.Row row:rows)panel.action("book",row.s("title"),null,false,()->bibleMenu(row));panel.show();});});}
 /** Comentários MyBible: load a .commentaries module, choose which one shows, show or hide, remove. */
 void commentaries(){UiPanel p=new UiPanel(this,"Comentários bíblicos",AppLanguage.text(this,"Aparecem por baixo do capítulo, com ✎ junto aos versículos"),"contents");long chosen=BibleComments.chosen(this);
  p.action("add","Carregar comentários (MyBible)","Ficheiro .commentaries.SQLite3",false,()->{try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),BIBLE_COMMENTS);}catch(Exception e){PlusUi.error(this,e);}});
  boolean show=getSharedPreferences(BibleComments.PREFS,0).getBoolean("show",true);p.action(show?"eye":"check",show?"Esconder comentários na leitura":"Mostrar comentários na leitura",null,false,()->getSharedPreferences(BibleComments.PREFS,0).edit().putBoolean("show",!show).apply());
  for(String[] c:BibleComments.all(this)){long id=Long.parseLong(c[0]);p.action(id==chosen?"check":"contents",c[1],AppLanguage.text(this,id==chosen?"Em uso · toque para remover":"Toque para usar"),false,()->{if(id!=chosen){BibleComments.choose(this,id);PlusUi.toast(this,c[1]);}else new UiDialog.Builder(this).setTitle("Remover este comentário?").setMessage("O ficheiro original continua na sua pasta.").setPositiveButton("Remover",(d,w)->PlusUi.run(this,()->BibleComments.delete(this,id))).setNegativeButton("Cancelar",null).show();});}
  p.show();}
 void loadComments(Uri uri){PlusUi.run(this,()->{File copy=new File(getCacheDir(),"comments-"+System.currentTimeMillis()+".sqlite3");try{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Ficheiro indisponível.");StudyFiles.copy(in,copy,268435456L,()->false);}String name=uri.getLastPathSegment()==null?"Comentário":uri.getLastPathSegment().replaceAll(".*[/:]","").replaceFirst("(?i)(\\.commentaries)?\\.sqlite3?$","");long[] r=BibleComments.load(this,copy,BibleMyBible.description(copy,name),()->false);PlusUi.post(this,()->PlusUi.toast(this,r[1]+" "+AppLanguage.text(this,"comentários carregados.")));}catch(Exception e){String m=e.getMessage();PlusUi.post(this,()->PlusUi.toast(this,m==null?AppLanguage.text(this,"Não foi possível ler os comentários."):m));}finally{copy.delete();}});}
 /** "Carregar títulos": copies the chosen MyBible module privately and reads its section titles. */
 void loadTitles(long source,Uri uri){PlusUi.run(this,()->{File copy=new File(getCacheDir(),"titles-"+source+".sqlite3");try{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Ficheiro indisponível.");StudyFiles.copy(in,copy,268435456L,()->false);}int n=BibleTitles.load(this,source,copy,()->false);PlusUi.post(this,()->PlusUi.toast(this,n+" "+AppLanguage.text(this,"títulos de secção carregados.")));}catch(Exception e){String m=e.getMessage();PlusUi.post(this,()->PlusUi.toast(this,m==null?AppLanguage.text(this,"Não foi possível ler os títulos."):m));}finally{copy.delete();}});}
 void pickBible(){pickBible("");}
 void pickBible(String edition){if(importing!=null){PlusUi.toast(this,"Aguarde a importação actual.");return;}EditText title=PlusUi.input(this,"Nome da tradução",edition.isEmpty()?"Minha Bíblia":edition,120);new UiDialog.Builder(this).setTitle("Importar Bíblia").setView(title).setPositiveButton("Escolher ficheiro",(d,w)->{bibleTitle=title.getText().toString().trim();if(bibleTitle.isEmpty())bibleTitle="Minha Bíblia";try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),BIBLE);}catch(Exception e){PlusUi.error(this,e);}}).setNegativeButton("Cancelar",null).show();}
 void pickUsxFolder(){EditText title=PlusUi.input(this,"Nome da tradução","Minha Bíblia USX",120);new UiDialog.Builder(this).setTitle("Importar pasta USX").setMessage("Escolha a pasta de uma versão, como nbv_usx ou release/USX_1. Pode incluir subpastas. Capas e configurações são ignoradas.").setView(title).setPositiveButton("Escolher pasta",(d,w)->{bibleTitle=title.getText().toString().trim();if(bibleTitle.isEmpty())bibleTitle="Minha Bíblia USX";try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),BIBLE_USX_FOLDER);}catch(Exception e){PlusUi.error(this,e);}}).setNegativeButton("Cancelar",null).show();}
 void importBible(Uri uri){BibleWork.enqueue(this,uri,bibleTitle.isEmpty()?"Minha Bíblia":bibleTitle,Intent.FLAG_GRANT_READ_URI_PERMISSION);}
 void bibleMenu(StudyStore.Row source){UiPanel panel=new UiPanel(this,source.s("title"),null,"book");panel.action("search","Abrir passagem",null,false,()->{EditText input=PlusUi.input(this,"Ex.: Isaías 3.1-7, 12 ou Salmo 23","",120);new UiDialog.Builder(this).setTitle("Passagem bíblica").setView(input).setPositiveButton("Abrir",(d,w)->{BibleReferences.Reference ref=BibleReferences.lookup(input.getText().toString());if(ref==null)PlusUi.toast(this,"Indique o livro e o capítulo.");else BibleLinks.passage(this,source,ref);}).setNegativeButton("Cancelar",null).show();});panel.action("contents","Carregar títulos (MyBible)","Títulos de secção: o módulo com títulos ou o ficheiro .subheadings",false,()->{titlesFor=source.id();try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),BIBLE_TITLES);}catch(Exception e){PlusUi.error(this,e);}});panel.danger("Eliminar esta Bíblia",()->new UiDialog.Builder(this).setTitle("Eliminar a Bíblia importada?").setMessage("O ficheiro original continua na sua pasta.").setPositiveButton("Eliminar",(d,w)->PlusUi.run(this,()->{try(PlusStore db=new PlusStore(this)){db.getWritableDatabase().beginTransaction();try{db.getWritableDatabase().delete("bible_verses","source=?",new String[]{""+source.id()});db.getWritableDatabase().delete("bible_sources","id=?",new String[]{""+source.id()});db.getWritableDatabase().setTransactionSuccessful();}finally{db.getWritableDatabase().endTransaction();}}BibleTitles.delete(this,source.id());PlusUi.post(this,this::bibles);})).setNegativeButton("Cancelar",null).show());panel.show();}
 void ocr(){new UiDialog.Builder(this).setTitle("Dados de OCR").setItems(new String[]{"Português · cerca de 2 MB","English · cerca de 4 MB"},(d,n)->{String language=n==1?"eng":"por";UiPanel panel=new UiPanel(this,"Dados de OCR",n==1?"English":"Português","scan");panel.action("download",OcrEngine.model(this,language).isFile()?"Verificar dados":"Descarregar dados",null,false,()->OcrWork.model(this,language));if(OcrEngine.model(this,language).isFile())panel.danger("Eliminar dados descarregados",()->new UiDialog.Builder(this).setTitle("Eliminar dados de OCR?").setMessage("O texto já reconhecido é conservado.").setPositiveButton("Eliminar",(x,w)->{if(OcrWork.modelsBusy()){PlusUi.toast(this,"Aguarde o OCR terminar.");return;}OcrEngine.model(this,language).delete();PlusUi.toast(this,"Dados removidos. O texto já reconhecido foi conservado.");}).setNegativeButton("Cancelar",null).show());panel.show();}).setNegativeButton("Fechar",null).show();}
 void licenses(){PlusUi.run(this,()->{String notice;try(InputStream in=getAssets().open("licenses/NOTICE.txt")){notice=new String(ContentText.read(in,200000),StandardCharsets.UTF_8);}final String value=notice;PlusUi.post(this,()->new UiDialog.Builder(this).setTitle("Licenças").setMessage(value).setPositiveButton("Fechar",null).show());});}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PhoneSync.FILES&&result==RESULT_OK&&data!=null){PhoneSync.sendFiles(this,data);return;}backup.result(request,result,data);revision.result(request,result,data);if(result==RESULT_OK&&data!=null&&data.getData()!=null){if(request==BIBLE_USX_FOLDER){BibleModuleWork.folder(this,data.getData(),bibleTitle.isEmpty()?"Minha Bíblia USX":bibleTitle,data.getFlags());}else if(request==BIBLE){ImportWork.permission(this,data.getData(),data.getFlags());importBible(data.getData());}else if(request==94)ApkInstallActivity.open(this,data.getData(),"Aplicação.apk");else if(request==BIBLE_TITLES&&titlesFor>0)loadTitles(titlesFor,data.getData());else if(request==BIBLE_COMMENTS)loadComments(data.getData());}}
 protected void onSaveInstanceState(Bundle state){state.putString("bible_title",bibleTitle);revision.save(state);super.onSaveInstanceState(state);}
 protected void onStart(){super.onStart();QuickSearchService.holdOverlay(hold,true);UiDialog.visibility(this,true);UiPanel.visibility(this,true);}protected void onStop(){QuickSearchService.holdOverlay(hold,false);UiDialog.visibility(this,false);UiPanel.visibility(this,false);super.onStop();}
 protected void onDestroy(){QuickSearchService.holdOverlay(hold,false);if(importing!=null)importing.set(true);backup.close();UiDialog.dismissAll(this);UiPanel.dismissAll(this);super.onDestroy();}
